using System.ComponentModel.DataAnnotations;

namespace CourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string Name { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9]+$", ErrorMessage = "Student ID must be alphanumeric.")]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = "MATH", Name = "Mathematics", Description = "Pure and applied mathematics, statistics, and data analysis." },
        new() { Id = "ENG", Name = "English", Description = "Literature, writing, and language studies." },
        new() { Id = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = "HIST", Name = "History", Description = "Exploration of past events and civilizations." },
    ];

    private readonly List<Course> _courses =
    [
        new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using C#. Covers variables, control flow, functions, and object-oriented basics.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Ada Lovelace", InstructorBio = "PhD in Computer Science from MIT. 15 years of teaching experience in introductory programming and software engineering.", DepartmentId = "CS", IsFeatured = true },
        new() { Id = 2, Code = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (arrays, trees, graphs) and algorithm design techniques (sorting, searching, dynamic programming).", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. Alan Turing", InstructorBio = "Researcher in computational complexity. Published over 40 papers on algorithm optimization.", DepartmentId = "CS", IsFeatured = true },
        new() { Id = 3, Code = "CS 310", Title = "Database Systems", Description = "Relational database design, SQL, normalization, transactions, and introduction to NoSQL systems.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Dr. Edgar Codd", InstructorBio = "Database architect with 20 years of industry experience. Former lead engineer at a Fortune 500 tech company.", DepartmentId = "CS", IsFeatured = false },
        new() { Id = 4, Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Emmy Noether", InstructorBio = "Award-winning mathematics educator specializing in making abstract concepts accessible to undergraduates.", DepartmentId = "MATH", IsFeatured = true },
        new() { Id = 5, Code = "MATH 201", Title = "Linear Algebra", Description = "Vectors, matrices, linear transformations, eigenvalues, and applications to data science.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Emmy Noether", InstructorBio = "Award-winning mathematics educator specializing in making abstract concepts accessible to undergraduates.", DepartmentId = "MATH", IsFeatured = false },
        new() { Id = 6, Code = "ENG 101", Title = "Composition & Rhetoric", Description = "Develop college-level writing skills. Emphasis on argumentation, research, and clarity.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Prof. Virginia Woolf", InstructorBio = "Published author and writing instructor. MFA from the Iowa Writers' Workshop.", DepartmentId = "ENG", IsFeatured = false },
        new() { Id = 7, Code = "ENG 220", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Prof. Toni Morrison", InstructorBio = "Specialist in American literary traditions with a focus on diverse voices and narrative techniques.", DepartmentId = "ENG", IsFeatured = true },
        new() { Id = 8, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes laboratory component.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Lab Thu 2:00–4:00 PM", InstructorName = "Dr. Richard Feynman", InstructorBio = "Engaging lecturer known for making complex physics intuitive. Research focus on quantum mechanics.", DepartmentId = "PHYS", IsFeatured = false },
        new() { Id = 9, Code = "PHYS 201", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM + Lab Fri 2:00–4:00 PM", InstructorName = "Dr. James Maxwell", InstructorBio = "Theoretical physicist with expertise in classical and quantum electrodynamics.", DepartmentId = "PHYS", IsFeatured = false },
        new() { Id = 10, Code = "HIST 101", Title = "World History to 1500", Description = "Major civilizations, trade networks, and cultural developments from prehistory to the early modern period.", Credits = 3, Schedule = "Mon/Wed 3:30–4:45 PM", InstructorName = "Prof. Howard Zinn", InstructorBio = "Historian specializing in social movements and underrepresented perspectives in world history.", DepartmentId = "HIST", IsFeatured = false },
    ];

    public IReadOnlyList<Department> GetDepartments() => _departments;

    public Department? GetDepartment(string id) =>
        _departments.FirstOrDefault(d => d.Id.Equals(id, StringComparison.OrdinalIgnoreCase));

    public IReadOnlyList<Course> GetAllCourses() => _courses;

    public IReadOnlyList<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) =>
        _courses.FirstOrDefault(c => c.Id == id);

    public IReadOnlyList<Course> SearchCourses(string? query, string? departmentId)
    {
        var results = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentId))
        {
            results = results.Where(c => c.DepartmentId.Equals(departmentId, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(query))
        {
            var q = query.Trim();
            results = results.Where(c =>
                c.Title.Contains(q, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(q, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(q, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(q, StringComparison.OrdinalIgnoreCase));
        }

        return results.ToList();
    }
}

